// 읽기 전용 화이트리스트. 데이터 API 경로를 요청에서 받지 않는다 (상태를 바꾸는 호출 없음).
const OPS = {
  tickets: '/tickets-created',
  alerts: '/alerts',
  dlq: '/dlq',
  logs: '/logs?limit=200',
  fault: '/admin/fault',
};
const body = $input.first().json.body;
const op = body && typeof body === 'object' && typeof body.op === 'string' ? body.op : '';
return [{ json: { op, ok: Object.prototype.hasOwnProperty.call(OPS, op), path: OPS[op] || '' } }];

// ↓ lib/common.js 원문 복사
function maskPII(text) {
  let masked = 0;
  let out = String(text == null ? '' : text);
  out = out.replace(/\b(01[016789])[-.\s]?(\d{3,4})[-.\s]?(\d{4})\b/g, (_, a, _b, c) => { masked++; return `${a}-****-${c}`; });
  out = out.replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, (_, first, domain) => { masked++; return `${first}***@${domain}`; });
  return { text: out, masked };
}
function maskDeep(value) {
  let masked = 0;
  const walk = v => {
    if (typeof v === 'string') { const r = maskPII(v); masked += r.masked; return r.text; }
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = walk(v[k]); return o; }
    return v;
  };
  return { value: walk(value), masked };
}
// ↑ lib/common.js 원문 복사 끝

const req = $('요청 검사').first().json;
const at = new Date().toISOString();
if (!req.ok) return [{ json: { op: req.op, error: 'unknown op', at } }];
const j = $input.first().json;
if (typeof j.statusCode !== 'number' || j.statusCode >= 300) {
  return [{ json: { op: req.op, error: 'data api ' + (j.statusCode || (j.error && (j.error.message || j.error)) || 'no response'), at } }];
}
// 연락처는 화면에 넘기기 전에 가린다.
return [{ json: { op: req.op, data: maskDeep(j.body).value, at } }];
